target.css:
:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --accent-gold: #c9a84c;
  --accent-gold-light: #e8c97a;
  --text-white: #f5f0e8;
  --text-muted: #a09080;
  --border-gold: #c9a84c;
  --divider-color: #c9a84c;
  --label-color: #a09080;
  --tag-bg: #c9a84c;
  --tag-text: #1a1a2e;
  --footer-border: #2e2e4e;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.invite-card {
  background-color: var(--bg-card);
  border: 2px solid var(--border-gold);
  border-radius: 4px;
  width: 460px;
  overflow: hidden;
  outline: 6px solid var(--bg-card);
  outline-offset: -10px;
}

.invite-header {
  background-color: var(--bg-header);
  padding: 28px 32px 22px;
  text-align: center;
  border-bottom: 1px solid var(--footer-border);
}

.invite-eyebrow {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--accent-gold);
  margin-bottom: 10px;
}

.invite-title {
  margin: 0 0 6px;
  font-size: 36px;
  font-weight: 300;
  color: var(--text-white);
  letter-spacing: 2px;
  line-height: 1.1;
}

.invite-subtitle {
  margin: 0;
  font-size: 13px;
  font-weight: 400;
  color: var(--text-muted);
  letter-spacing: 2px;
  font-style: italic;
}

.invite-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
}

.divider-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--divider-color);
}

.divider-line {
  flex: 1;
  height: 1px;
  background-color: var(--divider-color);
  opacity: 0.5;
}

.divider-diamond {
  font-size: 10px;
  color: var(--accent-gold-light);
  line-height: 1;
}

.invite-details {
  padding: 4px 32px 16px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 24px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.detail-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--label-color);
}

.detail-value {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-white);
  line-height: 1.3;
}

.invite-footer {
  border-top: 1px solid var(--footer-border);
  padding: 14px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.rsvp-tag {
  background-color: var(--tag-bg);
  color: var(--tag-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 2px;
}

.rsvp-contact {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

